export interface Page<T> {
	content: T[];
	first: boolean;
	hasNext: boolean;
	hasPrevious: boolean;
	last: boolean;
	number: number;
	numberOfElements: number;
	size: number;
	totalElements: number;
	totalPages: number;
}

export const emptyPage: Page<never> = {
	content: [],
	first: true,
	hasNext: false,
	hasPrevious: false,
	last: true,
	number: 0,
	numberOfElements: 0,
	size: 0,
	totalElements: 0,
	totalPages: 0
};

export enum SortDirection { ascending = 'asc', descending = 'desc' }

export class Sort {
	constructor(public field?: string, public direction: SortDirection = SortDirection.ascending) { }

	public getParamValue(): string | undefined {
		if (this.field) {
			return encodeURIComponent(this.field) + ',' + encodeURIComponent(this.direction);
		}
		return undefined;
	}

	public sortBy(field: string): void {
		if (this.field === field) {
			this.direction = this.direction === SortDirection.ascending ? SortDirection.descending : SortDirection.ascending;
		} else {
			this.field = field;
			this.direction = SortDirection.ascending;
		}
	}
}