import { HttpClient, HttpErrorResponse, HttpParams, HttpResponse } from '@angular/common/http';
import { AbstractControl, UntypedFormGroup } from '@angular/forms';
import {
	AlertDisplay,
	AlertListService,
	AlertType
} from 'espd-common/alert';
import {
	EspdFormGroup,
	isEspdControl
} from 'espd-common/forms/api';
import { MessageService } from 'espd-common/i18n';
import { ServiceLocator } from 'espd-common/utils';
import { Observable, throwError } from 'rxjs';
import { catchError, map, share } from 'rxjs/operators';
import { deserialize } from './json-deserialization';
import { HttpStatus } from './status-codes';

export class RequestOptions {
	handleErrors?: boolean;
	headers?: Record<string, string>;
	params?: HttpParams;
	responseType?: 'arraybuffer' | 'blob' | 'json' | 'text';
	showSuccessAlert?: boolean;
	successMessage?: string;
	validateForm?: boolean;
}

const requestOptionsProps = [
	'handleErrors',
	'headers',
	'params',
	'responseType',
	'showSuccessAlert',
	'successMessage',
	'validateForm'
];

export class HttpService {
	public static defaultOptions: RequestOptions = {
		handleErrors: true,
		showSuccessAlert: true,
		headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
		responseType: 'json',
		validateForm: true
	};

	private static defaultOptionsForGets: RequestOptions = {
		handleErrors: true,
		showSuccessAlert: true,
		headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
		responseType: 'json',
		validateForm: false
	};

	protected http?: HttpClient;
	protected alertService?: AlertListService;
	protected messageService?: MessageService;

	constructor() {
		this.http = ServiceLocator.get(HttpClient);
		this.alertService = ServiceLocator.get(AlertListService);
		this.messageService = ServiceLocator.get(MessageService);
	}

	protected get<T>(url: string): Observable<T>;
	protected get<T>(url: string, options?: RequestOptions): Observable<T>;
	protected get<T>(url: string, deserializationClass: any): Observable<T>;
	protected get<T>(url: string, deserializationClass: any, options?: RequestOptions): Observable<T>;
	protected get<T>(url: string, optionsOrClass?: any, options?: RequestOptions): Observable<T> {
		const requestOptions = this.getOptions(optionsOrClass, options, HttpService.defaultOptionsForGets);
		const deserializationClass = this.getDeserializationClass(optionsOrClass);

		return this.http!.request('GET', url, {
			headers: requestOptions.headers,
			params: requestOptions.params,
			responseType: requestOptions.responseType
		}).pipe(
			catchError((error: unknown) => requestOptions?.handleErrors ? this.handleError(error as HttpErrorResponse) : throwError(error)),
			map(body => deserializationClass ? deserialize<T>(body, deserializationClass) : body),
			share());
	}

	protected post<T>(url: string, data: any): Observable<T>;
	protected post<T>(url: string, data: any, options?: RequestOptions): Observable<T>;
	protected post<T>(url: string, data: any, deserializationClass: any): Observable<T>;
	protected post<T>(url: string, data: any, deserializationClass: any, options?: RequestOptions): Observable<T>;
	protected post<T>(url: string, data: any, optionsOrClass?: any, options?: RequestOptions): Observable<T> {
		const requestOptions = this.getOptions(optionsOrClass, options);
		const deserializationClass = this.getDeserializationClass(optionsOrClass);

		const body: any = data ? JSON.stringify(data) : null;
		const response: Observable<T> = this.http!.request('POST', url, {
			body,
			headers: requestOptions.headers,
			params: requestOptions.params,
			responseType: requestOptions.responseType,
		}).pipe(
			catchError((error: unknown) => requestOptions?.handleErrors ? this.handleError(error as HttpErrorResponse) : throwError(error)),
			map(responseBody => deserializationClass ? deserialize<T>(responseBody, deserializationClass) : responseBody),
			share()
		);
		if (requestOptions.successMessage) {
			response.subscribe({
				complete: () => {
					this.alertService?.addAlert(requestOptions.successMessage!, AlertType.success, undefined, AlertDisplay.growl);
				}, error: (err: unknown) => err
			});
		}
		return response;
	}

	protected postForm<T>(url: string, data: any, form: EspdFormGroup): Observable<HttpResponse<T>>;
	protected postForm<T>(url: string, data: any, form: EspdFormGroup, options?: RequestOptions): Observable<HttpResponse<T>>;
	protected postForm<T>(url: string, data: any, form: EspdFormGroup, deserializationClass: any): Observable<HttpResponse<T>>;
	protected postForm<T>(url: string, data: any, form: EspdFormGroup, deserializationClass: any, options?: RequestOptions): Observable<HttpResponse<T>>;
	protected postForm<T>(url: string, data: any, form: EspdFormGroup, optionsOrClass?: any, options?: RequestOptions): Observable<HttpResponse<T>> {
		const requestOptions = this.getOptions(optionsOrClass, options);
		const deserializationClass = this.getDeserializationClass(optionsOrClass);

		form.isSubmitted = !!requestOptions.validateForm;
		form.clearServerErrors();
		if (requestOptions.validateForm && form.invalid) {
			this.handleFocus();
			return throwError('form is invalid');
		}
		const responseObs: Observable<HttpResponse<T>> = this.http!.post<T>(url, JSON.stringify(data), { headers: requestOptions.headers, observe: 'response', params: requestOptions.params })
			.pipe(
				catchError((error: unknown) => {
					this.handleFocus();
					const status = (error as HttpErrorResponse).status;
					if (status === HttpStatus.unprocessableEntity) { // (validation error)
						this.applyErrorsToFormGroup((error as HttpErrorResponse).error, form);
						return throwError(() => error);
					} else {
						return requestOptions?.handleErrors ? this.handleError(error as HttpErrorResponse) : throwError(error);
					}
				}),
				map(httpResponse => deserializationClass ? httpResponse.clone({ body: deserialize<T>(httpResponse.body, deserializationClass) }) : httpResponse),
				share());
		if (requestOptions.showSuccessAlert) {
			responseObs.subscribe({
				complete: () => {
					this.alertService?.addSaveSuccessMessage(requestOptions.successMessage);
				}, error: (err: unknown) => err
			});
		}
		return responseObs;
	}

	protected postText(url: string, data: any, bodyContentType?: string, options?: RequestOptions): Observable<string> {

		const headers: Record<string, string> = { Accept: 'text/plain' };

		if (bodyContentType) {
			headers['Content-Type'] = bodyContentType;
		}

		options = this.optionsWithDefaults({ responseType: 'text', headers }, HttpService.defaultOptionsForGets);

		const response: Observable<string> = this.http!.request('POST', url, { body: data, headers: options.headers, responseType: options.responseType })
			.pipe(
				catchError((error: unknown) => options?.handleErrors ? this.handleError(error as HttpErrorResponse) : throwError(error)),
				share()
			);
		if (response && options?.successMessage) {
			response.subscribe({
				complete: () => {
					this.alertService?.addSaveSuccessMessage(options.successMessage);
				}, error: (err: unknown) => err
			});
		}
		return response;
	}

	protected delete<T>(url: string): Observable<HttpResponse<T>>;
	protected delete<T>(url: string, options?: RequestOptions): Observable<HttpResponse<T>>;
	protected delete<T>(url: string, deserializationClass: any): Observable<HttpResponse<T>>;
	protected delete<T>(url: string, deserializationClass: any, options?: RequestOptions): Observable<HttpResponse<T>>;
	protected delete<T>(url: string, optionsOrClass?: any, options?: RequestOptions): Observable<HttpResponse<T>> {
		const requestOptions = this.getOptions(optionsOrClass, options);
		const deserializationClass = this.getDeserializationClass(optionsOrClass);

		const response: Observable<HttpResponse<T>> = this.http!.request('DELETE', url, {
			headers: requestOptions.headers,
			observe: 'response',
			params: requestOptions.params,
			responseType: requestOptions.responseType
		}).pipe(
			catchError((error: unknown) => {
				const errorResponse = error as HttpErrorResponse;
				if (requestOptions?.handleErrors) {
					return this.handleError(errorResponse);
				} else {
					return throwError(() => errorResponse);
				}
			}),
			map(httpResponse => deserializationClass ? httpResponse.clone({ body: deserialize<T>(httpResponse.body, deserializationClass) }) : httpResponse),
			share()
		);
		if (requestOptions.showSuccessAlert) {
			response.subscribe({
				complete: () => {
					this.alertService?.addDeleteSuccessMessage(requestOptions.successMessage);
				}, error: (err: unknown) => err
			});
		}
		return response;
	}

	protected handleFocus(): void {
		setTimeout(() => {
			const firstError: HTMLElement = document.querySelector('.ng-invalid:not(form)')!;
			if (firstError) {
				firstError.focus();
				firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
			}
		});
	}

	protected handleError(error: HttpErrorResponse): Observable<never> {
		if (error.status !== HttpStatus.unauthorized) {
			const message: string = this.messageService?.get('common.alert.error') ?? '';
			// eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
			const errMsg = `${message}<br />${error.error?.message || error.message || ''}`;
			this.alertService?.addAlert(errMsg, AlertType.danger, undefined, AlertDisplay.growl);
			return throwError(() => errMsg);
		} else {
			return throwError(() => error);
		}
	}

	private applyErrorsToFormGroup(messages: any, formGroup: UntypedFormGroup) {
		// error message structure
		/*
		 * {
		 * 		'formFieldName': ['messages'],
		 * 		'nested[1].name': ['messages']
		 * }
		 */
		for (const field in messages) {
			const control: AbstractControl | null = this.getFormControl(field, formGroup);
			if (isEspdControl(control)) {
				control.serverErrors = messages[field];
			}
		}
	}

	private getFormControl(controlName: string, formGroup: UntypedFormGroup): AbstractControl | null {
		return formGroup.get(controlName.replace(/\[(\d+)\]/, '.$1'));
	}

	protected optionsWithDefaults(options?: RequestOptions, defaultOptions: RequestOptions = HttpService.defaultOptions): RequestOptions {
		if (!options) {
			options = defaultOptions;
		} else {
			options = { ...defaultOptions, ...options };
			options.headers = { ...defaultOptions.headers, ...options.headers };
		}
		return options;
	}

	private getOptions(optionsOrClass?: any, options?: RequestOptions, defaults?: RequestOptions): RequestOptions {
		let requestOptions: RequestOptions | undefined = options;
		if (this.isRequestOptions(optionsOrClass)) {
			requestOptions = optionsOrClass;
		}
		return this.optionsWithDefaults(requestOptions, defaults);
	}

	private getDeserializationClass(optionsOrClass?: any): any {
		if (!!optionsOrClass && !this.isRequestOptions(optionsOrClass)) {
			return optionsOrClass;
		}
		return null;
	}

	private isRequestOptions(obj: any): obj is RequestOptions {
		const isObject = !!obj && typeof obj === 'object' && !Array.isArray(obj);
		return isObject && Object.keys(obj).every(key => requestOptionsProps.includes(key));
	}
}