import { HttpResponse } from '@angular/common/http';

import { Observable } from 'rxjs';
import { HttpService, RequestOptions } from './http.service';
import { EspdFormGroup } from 'espd-common/forms/api';
import { Page } from './page.model';

export abstract class RestDataService<T> extends HttpService {

	protected abstract get baseUrl(): string;

	public getAll(): Observable<T[]> {
		return this.get(`${this.baseUrl}/all`);
	}

	public search(query: Record<string, string | number | boolean | null | undefined | (string | number | boolean | null | undefined)[]>): Observable<Page<T>> {
		return this.query('', query);
	}

	public getById(id: number | string): Observable<T> {
		return this.get(`${this.baseUrl}/${id}`); //`
	}

	public save(data: T, form: EspdFormGroup, options?: RequestOptions): Observable<HttpResponse<any>> {
		return this.postForm(this.baseUrl, data, form, options);
	}

	public deleteById(id: number, options?: RequestOptions): Observable<HttpResponse<any>> {
		return this.delete(`${this.baseUrl}/${id}`, options); //`
	}

	public query<ResultType>(url: string, query: Record<string, string | number | boolean | null | undefined | (string | number | boolean | null | undefined)[]>): Observable<ResultType> {
		Object.keys(query).forEach((k) => query[k] == null && delete query[k]); // the == instead of === is intentional to check both null and undefined

		const queryString = Object.keys(query)
			.map(key => `${encodeURIComponent(key)}=${this.convertQueryValue(query[key]!)}`).join('&'); //`
		return this.get(`${this.baseUrl}${url}?${queryString}`); //`
	}

	protected convertQueryValue(value: any): string {
		if (Array.isArray(value)) {
			value = value.filter(v => v != null).join(',');
		}
		return encodeURIComponent(value);
	}
}